def slugify(s):
    s = re.sub(r'[<>:"/\\|?*\s]+', "-", str(s or "").strip())
    return s.strip("-.") or "goal"


# ---------------------------------------------------------------- 选方法（纯函数）

def method_quote_stats(m):
    """返回 (quote 条数, 数字未落引文条数)。L1 无 quote ⇒ (0,0)。"""
    quoted = bad = 0
    for fld in ("materials", "equipment", "parameters", "steps",
                "characterization", "key_metrics"):
        for it in m.get(fld) or []:
            if not isinstance(it, dict):
                continue
            if it.get("quote"):
                quoted += 1
            if it.get("value_in_quote") is False:
                bad += 1
    return quoted, bad


def _method_text(m):
    parts = [m.get("name_zh") or "", m.get("name_en") or "", m.get("summary") or ""]
    for fld in ("materials", "parameters", "key_metrics"):
        for it in m.get(fld) or []:
            if isinstance(it, dict):
                parts.extend(str(it.get(k) or "") for k in
                             ("name", "metric", "value", "role") if it.get(k))
    return " ".join(parts)


def char_names(m):
    """表征列表可能是 str（L1）或 {technique, quote}（L2），统一成名字列表。"""
    out = []
    for c in m.get("characterization") or []:
        name = c.get("technique") if isinstance(c, dict) else str(c)
        if name:
            out.append(name)
    return out


def score_method(m, goal_tokens):
    text = _method_text(m).lower()
    return sum(3 if t in str(m.get("name_zh") or "").lower() else
               (1 if t in text else 0) for t in goal_tokens)


def _goal_tokens(goal):
    """目标词 = 用户用空格/标点分隔的子串本体。

    不用 jieba：`kb_lib.tokenize` 会丢掉单字词（实测「锌 沉积」只剩「沉积」），
    导致「只命中一个泛词」也算匹配——直接把锂电电解液论文当成锌沉积方案。
    """
    chunks = [c.strip() for c in re.split(r"[\s,，、/]+", str(goal or "")) if c.strip()]
    return list(dict.fromkeys(chunks))


def select_methods(methods, goal, category=None, top=3):
    """按目标词选方法：要求目标词**基本全中**（≥80%），再按命中数/证据质量排序。

    只命中一个泛词（如"沉积"）不算匹配——实测会把锂电电解液论文当成锌沉积方案。
    """
    tokens = _goal_tokens(goal)
    if not tokens:
        return []
    need = max(1, int(len(tokens) * 0.8 + 0.999))
    scored = []
    for m in methods:
        if category and m.get("category") != category:
            continue
        text = _method_text(m).lower()
        name = str(m.get("name_zh") or "").lower()
        hits = [t for t in tokens if t in text or t in name]
        if len(hits) < need:
            continue
        quoted, bad = method_quote_stats(m)
        scored.append({"method": m, "match": len(hits), "quoted": quoted,
                       "bad": bad, "rank_score": round(len(hits) * 10 + quoted - 2 * bad, 3)})
    scored.sort(key=lambda x: (-x["match"], -(x["quoted"] - 2 * x["bad"]),
                               x["method"]["name_zh"]))
    # 有带引文的候选时，不把 0 引文的 L1 混进对比表（L1 只作补充）
    if any(s["quoted"] > 0 for s in scored):
        scored = [s for s in scored if s["quoted"] > 0]
    return scored[:top]


def find_method(methods, method_id):
    for m in methods:
        if m.get("method_id") == method_id or m.get("name_zh") == method_id:
            return m
    return None


# ---------------------------------------------------------------- 判断层（LLM 合成 + quote 校验）
ASSESS_SCHEMA = """判断层 schema（每个方法一条）：
{
  "method_id": "方法库里的 method_id",
  "advantages": [{"text": "优势（一句话，可比较）", "quote": "该判断所依据的原文片段"}],
  "conditions": [{"text": "适用条件（温度/体系/规模/前提）", "quote": "原文片段"}],
  "limits":     [{"text": "局限或风险", "quote": "原文片段"}]
}
🔴 只允许使用 assess_jobs.json 里给出的 evidence；quote 必须逐字来自卡片正文。
   找不到依据就不要写这一条——宁缺勿造。"""


def _norm(s):
    return re.sub(r"\s+", " ", str(s or "")).strip()


def method_body(m, bodies=None):
    if bodies and m.get("method_id") in bodies:
        return _norm(bodies[m["method_id"]])
    p = m.get("page_path") or ""
    if p and os.path.isfile(os.path.join(K.VAULT, p)):
        return _norm(K.read_text(os.path.join(K.VAULT, p)))
    return ""


def build_assessment_jobs(goal, selected):
    ms = []
    for s in selected:
        m = s["method"]
        ev = []
        for fld in ("materials", "parameters", "steps", "characterization", "key_metrics"):
            for it in (m.get(fld) or [])[:5]:
                if isinstance(it, dict) and it.get("quote"):
                    txt = (it.get("name") or it.get("action") or
                           it.get("technique") or it.get("metric") or "")
                    ev.append({"field": fld, "text": txt, "quote": it["quote"]})
        ms.append({"method_id": m["method_id"], "name_zh": m.get("name_zh"),
                   "category": m.get("category"), "summary": m.get("summary") or "",
                   "evidence": ev})
    return {"goal": goal, "schema": ASSESS_SCHEMA, "methods": ms}


def validate_judgement(j, body):
    out = {"method_id": j.get("method_id"), "advantages": [], "conditions": [],
           "limits": [], "quotes_checked": 0, "quotes_failed": 0}
    for key in ("advantages", "conditions", "limits"):
        for it in j.get(key) or []:
            if not isinstance(it, dict):
                continue
            q = _norm(it.get("quote"))
            out["quotes_checked"] += 1
            if not q or q not in body:
                out["quotes_failed"] += 1
                continue
            out[key].append({"text": str(it.get("text") or "").strip(), "quote": it["quote"]})
    return out


def merge_assessments(methods, judges, bodies=None):
    by = {m["method_id"]: m for m in methods}
    merged = []
    stats = {"checked": 0, "failed": 0, "judged": 0}
    for j in judges:
        m = by.get(j.get("method_id"))
        if not m:
            continue
        v = validate_judgement(j, method_body(m, bodies))
        stats["checked"] += v["quotes_checked"]
        stats["failed"] += v["quotes_failed"]
        if v["advantages"] or v["conditions"] or v["limits"]:
            m["judgements"] = v
            merged.append(m["method_id"])
            stats["judged"] += 1
    return merged, stats


# ---------------------------------------------------------------- 渲染

def _q(it, text=None):
    q = (it.get("quote") or "").strip()
    val = text if text is not None else ""
    line = f"{val}"
    if q:
        line += f" ｜ 引文：{q}"
    if it.get("value_in_quote") is False:
        line += " ｜ ⚠️ 数字未出现在引文中"
    return line


def fmt_value(it):
    """值 + 单位；值里已经带了单位就不再重复（实测出现过 `10 s / 10 s / 10 ss`）。"""
    v = str(it.get("value") or "").strip()
    u = str(it.get("unit") or "").strip()
    if not u or not v:
        return v + u
    if u in v or v.endswith(u):
        return v
    return v + u


def render_strategy(goal, selected, category=None):
    L = [f"# 策略层：{goal}", ""]
    L.append(f"> 生成于 {datetime.date.today().isoformat()} ｜ 来源：`methods_db.json` ｜ "
             f"候选 {len(selected)} 个"
             + (f" ｜ 限定类别：{category}" if category else ""))
    L.append("> 🔴 本表是**事实型对比**：只列方法库里有原文依据的字段。"
             "「核心优势 / 适用条件」需要判断，v0 不生成——请基于引文自行判断，勿把本表当结论。")
    if any(s["method"].get("judgements") for s in selected):
        L.append("> 判断层（如有）是 **LLM 基于所列引文的合成判断**，每条挂引文；"
                 "与事实层分开阅读，事实层不受影响。")
    L.append("")
    L.append("| # | 方法 | 类别 | 来源层 | 证据引文 | 可核验 | 关键参数 | 材料 | 表征 |")
    L.append("|---|---|---|---|---|---|---|---|---|")
    for i, s in enumerate(selected, 1):
        m = s["method"]
        params = "；".join(f"{p.get('name') or ''}={fmt_value(p)}"
                          for p in (m.get("parameters") or m.get("parameters_raw") or [])[:3])
        mats = "；".join(str(x.get("name") or "") for x in (m.get("materials") or [])[:3])
        chars = "、".join(char_names(m)[:5])
        verify = "—" if s["quoted"] == 0 else f"{s['quoted'] - s['bad']}/{s['quoted']}"
        L.append(f"| {i} | {m.get('name_zh')} | {m.get('category')} | {m.get('tier')} | "
                 f"{s['quoted']} | {verify} | {params or '—'} | {mats or '—'} | {chars or '—'} |")
    L.append("")
    L.append("## 逐条依据")
    L.append("")
    for i, s in enumerate(selected, 1):
        m = s["method"]
        L.append(f"### {i}. {m.get('name_zh')}（`{m.get('method_id')}`）")
        L.append("")
        L.append(f"- 类别：{m.get('category')} ｜ 来源：{m.get('source_ref')}")
        if m.get("summary"):
            L.append(f"- 摘要：{m['summary']}")
        for it in (m.get("materials") or [])[:3]:
            L.append(f"- 材料 {it.get('name') or '—'} {it.get('amount') or ''}：{_q(it)}")
        for p in (m.get("parameters") or m.get("parameters_raw") or [])[:5]:
            L.append(f"- 参数 {p.get('name') or '—'} = {fmt_value(p)}："
                     + _q(p))
        for st in (m.get("steps") or [])[:3]:
            L.append(f"- 步骤 {st.get('order')}：{st.get('action') or ''} {st.get('detail') or ''}："
                     + _q(st))
        for it in (m.get("key_metrics") or [])[:3]:
            L.append(f"- 指标 {it.get('metric') or ''} = {fmt_value(it)}："
                     + _q(it))
        j = m.get("judgements")
        if j:
            L.append("")
            L.append("**判断层（LLM 合成，逐条带引文）**")
            for label, key in (("优势", "advantages"), ("适用条件", "conditions"),
                               ("局限/风险", "limits")):
                for it in j.get(key) or []:
                    L.append(f"- {label}：{it.get('text') or ''} ｜ 引文：{it.get('quote')}")
        L.append("")
    L.append("## 下一步")
    L.append("")
