CHAIN_REL = "projects/sci-assistant/knowledge/chains.json"


def render_chain_section(selected_ids, limit=8):
    """把 chains.json 里与本次候选相关的方法链接到策略层末尾（没有就返回空串）。"""
    p = os.path.join(K.VAULT, CHAIN_REL)
    if not os.path.isfile(p):
        return ""
    edges = json.load(open(p, encoding="utf-8")).get("edges") or []
    rows = [e for e in edges
            if e.get("from") in selected_ids or e.get("to") in selected_ids]
    if not rows:
        return ""
    # 术语共享的强边优先展示；类别级弱边最多 4 条，避免把策略层淹掉
    term = [e for e in rows if e.get("evidence_level") == "term"]
    weak = [e for e in rows if e.get("evidence_level") != "term"]
    rows = term[:limit] + weak[:max(0, min(4, limit - len(term[:limit])))]
    L = ["## 方法链（产出 → 输入）", "",
         "> 由 `sci_method_chain.py` 生成，每条边两侧的 quote 都已通过原文连续子串校验。",
         "> 「术语共享」= 产出物与输入物共享具体名词；「类别级（弱）」= 只按方法类别衔接，"
         "**不保证同一材料体系**。依赖关系是推断，不是作者明示的因果。", ""]
    for e in rows[:limit]:
        tag = "术语共享" if e.get("evidence_level") == "term" else "类别级（弱）"
        L.append(f"- {e['from_name']} —产出「{e['artifact']}」→ {e['to_name']}"
                 f"（需要「{e['matched_input']}」）｜ {tag}")
    L.append("")
    return "\n".join(L)


def render_operation(m):
    L = [f"# 操作层：{m.get('name_zh')}", ""]
    L.append(f"> 来源：{m.get('source_ref')} ｜ 类别：{m.get('category')} ｜ "
             f"置信度：{m.get('extraction_confidence')} ｜ reviewed={m.get('reviewed')}")
    L.append("> 🔴 每个值后面都带原文引文；标 ⚠️ 的条目其**数字未出现在引文里**，"
             "使用前必须回原文核对。L2 记录用于策略层，操作层建议再核 L3 全文。")
    L.append("")
    if m.get("summary"):
        L.append(f"**摘要**：{m['summary']}")
        L.append("")
    L.append("## 材料")
    L.append("")
    L.append("| 名称 | 用量 | 角色 | 引文 |")
    L.append("|---|---|---|---|")
    for it in m.get("materials") or []:
        L.append(f"| {it.get('name') or '—'} | {it.get('amount') or '—'} | "
                 f"{it.get('role') or '—'} | {it.get('quote') or '—'} |")
    if not m.get("materials"):
        L.append("| — | — | — | 原文未给出 |")
    L.append("")
    L.append("## 设备")
    L.append("")
    L.append("| 类型 | 型号 | 引文 |")
    L.append("|---|---|---|")
    for it in m.get("equipment") or []:
        L.append(f"| {it.get('type') or '—'} | {it.get('model') or '—'} | {it.get('quote') or '—'} |")
    if not m.get("equipment"):
        L.append("| — | — | 原文未给出型号 |")
    L.append("")
    L.append("## 关键参数")
    L.append("")
    L.append("| 参数 | 值 | 单位 | 引文 |")
    L.append("|---|---|---|---|")
    for it in (m.get("parameters") or m.get("parameters_raw") or []):
        flag = " ⚠️" if it.get("value_in_quote") is False else ""
        L.append(f"| {it.get('name') or '—'}{flag} | {it.get('value') or '—'} | "
                 f"{it.get('unit') or '—'} | {it.get('quote') or '（概念页参数上下文）'} |")
    L.append("")
    L.append("## 操作步骤")
    L.append("")
    steps = m.get("steps") or []
    if steps:
        for st in steps:
            L.append(f"{st.get('order')}. **{st.get('action') or ''}** — {st.get('detail') or ''}"
                     + (f" ｜ 引文：{st.get('quote')}" if st.get("quote") else ""))
    else:
        L.append("（原文未给出可执行步骤；需从 L3 全文补充。）")
    L.append("")
    L.append("## 表征")
    L.append("")
    chars = m.get("characterization") or []
    if chars:
        if isinstance(chars[0], dict):
            for it in chars:
                L.append(f"- {it.get('technique')}" + (f" ｜ 引文：{it.get('quote')}"
                                                       if it.get("quote") else ""))
        else:
            L.append("- " + "、".join(chars))
    else:
        L.append("（原文未列表征。）")
    L.append("")
    L.append("## 性能指标")
    L.append("")
    L.append("| 指标 | 值 | 单位 | 条件 | 引文 |")
    L.append("|---|---|---|---|---|")
    for it in m.get("key_metrics") or []:
        flag = " ⚠️" if it.get("value_in_quote") is False else ""
        L.append(f"| {it.get('metric') or '—'}{flag} | {it.get('value') or '—'} | "
                 f"{it.get('unit') or '—'} | {it.get('condition') or '—'} | {it.get('quote') or '—'} |")
    if not m.get("key_metrics"):
        L.append("| — | — | — | — | 原文未给出 |")
    L.append("")
    L.append("## 注意事项 / 陷阱")
    L.append("")
    pitfalls = m.get("pitfalls") or []
    if pitfalls:
        for p in pitfalls:
            L.append(f"- {p}")
    else:
        L.append("（方法库未收录该方法的陷阱；L2 的批判性标记需回原文核对。）")
    L.append("")
    L.append("## 证据")
    L.append("")
    L.append(f"- {m.get('source_ref')}")
    L.append("")
    return "\n".join(L)


# ---------------------------------------------------------------- 输出

def out_dir(cfg, goal):
    base = (cfg.get("sci") or {}).get("protocols_dir") or "projects/sci-assistant/protocols"
    return os.path.join(K.VAULT, base, slugify(goal))


def write_text(path, text):
    """写盘并复算；**覆盖前先备份**（同一 goal 换类别/重跑会覆盖，2026-10-20 踩过一次）。"""
    import shutil
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.isfile(path):
        old = K.read_text(path)
        if old.strip() and old.rstrip("\n") != text.rstrip("\n"):
            bak_dir = os.path.join(K.VAULT, "_scratch", "backup", "protocols")
            os.makedirs(bak_dir, exist_ok=True)
            rel = os.path.relpath(path, K.VAULT).replace(os.sep, "__")
            ts = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
            shutil.copy2(path, os.path.join(bak_dir, f"{rel}.{ts}.bak"))
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text + "\n")
    with open(path, encoding="utf-8") as f:
        back = f.read()
    if not back.strip():
        raise SystemExit(f"[!] 写盘复算失败: {path}")
    return path


