def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    m1 = {"method_id": "source:A", "name_zh": "锌沉积法", "category": "合成", "tier": "source",
          "source_ref": "[[sources/A]]", "summary": "", "materials": [
              {"name": "ZnSO4", "amount": "5.75 g", "role": "锌盐", "quote": "5.75 g ZnSO4"}],
          "equipment": [], "parameters": [
              {"name": "电流密度", "value": "1.0", "unit": "mA cm⁻²",
               "quote": "1.0 mA cm⁻²", "value_in_quote": True}],
          "steps": [{"order": 1, "action": "配液", "detail": "", "quote": "配制电解液"}],
          "characterization": [{"technique": "SEM", "quote": "SEM"}],
          "key_metrics": [{"metric": "CE", "value": "99.9", "unit": "%",
                           "condition": "1 mA cm⁻²", "quote": "CE 99.9%"}],
          "pitfalls": [], "extraction_confidence": "medium", "reviewed": False}
    m2 = dict(m1)
    m2.update({"method_id": "source:B", "name_zh": "锌沉积法B",
               "parameters": [{"name": "温度", "value": "25", "unit": "°C",
                               "quote": "25 °C", "value_in_quote": False}]})
    methods = [m1, m2,
               {"method_id": "concept:C", "name_zh": "电解液设计", "category": "计算",
                "tier": "concept", "source_ref": "[[concepts/C]]", "summary": "计算方向",
                "parameters_raw": [{"value": "100", "unit": "ns", "context": "MD 100 ns"}],
                "characterization": ["DFT"], "steps": [], "materials": [], "equipment": [],
                "key_metrics": [], "pitfalls": []}]

    sel = select_methods(methods, "锌 沉积", top=2)
    chk("选择：按目标词命中排序", len(sel) == 2 and sel[0]["method"]["method_id"] == "source:A")
    chk("选择：类别过滤", all(x["method"]["category"] == "合成"
                              for x in select_methods(methods, "锌 沉积", category="合成")))
    chk("选择：无命中返回空", select_methods(methods, "完全无关的词", top=3) == [])
    chk("选择：证据质量参与排序（A 无坏值，B 有坏值）",
        select_methods(methods, "锌 沉积", top=2)[0]["bad"] == 0)

    s_md = render_strategy("锌 沉积", sel)
    chk("策略层：含对比表与事实型声明",
        "| # | 方法 |" in s_md and "事实型对比" in s_md and "不生成" in s_md)
    chk("策略层：逐条带引文", "5.75 g ZnSO4" in s_md)

    op = render_operation(m1)
    chk("操作层：含材料/参数/步骤/表征/指标",
        all(h in op for h in ("## 材料", "## 关键参数", "## 操作步骤",
                              "## 表征", "## 性能指标")))
    chk("操作层：参数带引文", "1.0 mA cm⁻²" in op)
    bad_op = render_operation(m2)
    chk("操作层：数字未落引文有显式警示", "⚠️" in bad_op and "数字未出现在引文" in bad_op)

    chk("查找：按 method_id 命中", find_method(methods, "source:B") is methods[1])
    chk("查找：不存在返回 None", find_method(methods, "nope") is None)

    jobs = build_assessment_jobs("锌 沉积", sel)
    chk("判断层：任务带 evidence",
        bool(jobs["methods"][0]["evidence"]) and
        bool(jobs["methods"][0]["evidence"][0]["quote"]))
    body = "5.75 g ZnSO4 配制，1.0 mA cm⁻² 测试，CE 99.9%。"
    good = {"method_id": "source:A",
            "advantages": [{"text": "浓度可核", "quote": "5.75 g ZnSO4"}],
            "conditions": [], "limits": []}
    bad = {"method_id": "source:A",
           "advantages": [{"text": "编的", "quote": "999 g 不存在"}]}
    v = validate_judgement(good, body)
    chk("判断层：合法引文保留", len(v["advantages"]) == 1 and v["quotes_failed"] == 0)
    v2 = validate_judgement(bad, body)
    chk("判断层：伪造引文丢弃", not v2["advantages"] and v2["quotes_failed"] == 1)
    merged, st = merge_assessments([m1, m2], [good], bodies={"source:A": body})
    chk("判断层：合并挂到方法并统计", merged == ["source:A"] and st["judged"] == 1)
    md2 = render_strategy("锌 沉积", [{"method": m1, "match": 2, "quoted": 1,
                                       "bad": 0, "rank_score": 21}])
    chk("判断层：策略层渲染判断与引文",
        "判断层" in md2 and "5.75 g ZnSO4" in md2)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="两层实验方案生成（Phase 2b，事实型 v0）")
    ap.add_argument("--goal", help="目标（如 \"锌负极 沉积\"）")
    ap.add_argument("--category", choices=CATEGORIES, help="限定方法类别")
    ap.add_argument("--top", type=int, default=3, help="策略层候选数（默认 3）")
    ap.add_argument("--choose", help="选定的 method_id（生成操作层）")
    ap.add_argument("--methods", default=None, help="methods_db.json 路径覆盖")
    ap.add_argument("--assess", action="store_true",
                    help="生成判断层任务（assess_jobs.json，交 LLM 合成优势/条件/局限）")
    ap.add_argument("--judges", default=None,
                    help="判断层结果 JSON（--assess 的产出经 LLM 返回后合并）")
    ap.add_argument("--json", action="store_true", help="结果 JSON 打印到 stdout")
    ap.add_argument("--no-write", action="store_true", help="不写盘")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖知识库）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not (args.goal or args.choose):
        ap.print_help()
        return 1

    cfg = load_config()
    methods = load_methods(cfg, args.methods)

    if args.choose:
        m = find_method(methods, args.choose)
        if not m:
            raise SystemExit(f"[!] 找不到方法: {args.choose}")
        md = render_operation(m)
        goal = args.goal or m.get("name_zh")
        d = out_dir(cfg, goal)
        if args.json:
            print(json.dumps(m, ensure_ascii=False, indent=2))
        if not args.no_write:
            p_md = write_text(os.path.join(d, "operation-" + slugify(m.get("name_zh")) + ".md"), md)
            p_js = os.path.join(d, "operation-" + slugify(m.get("name_zh")) + ".json")
            write_text(p_js, json.dumps(m, ensure_ascii=False, indent=2))
            print(f"[ok] 操作层：{m.get('name_zh')}（{m.get('category')}）")
            print(f"     输出: {os.path.relpath(p_md, K.VAULT)}")
        return 0

    selected = select_methods(methods, args.goal, args.category, args.top)
    if not selected:
        raise SystemExit(f"[!] 方法库中没有与「{args.goal}」匹配的方法"
                         "（试试更宽的目标词，或先补方法库）")
    d = out_dir(cfg, args.goal)

    if args.assess:
        jobs = build_assessment_jobs(args.goal, selected)
        p = os.path.join(d, "assess_jobs.json")
        write_text(p, json.dumps(jobs, ensure_ascii=False, indent=2))
        print(f"[ok] 判断层任务：{len(jobs['methods'])} 个方法，每题带 evidence")
        print(f"     输出: {os.path.relpath(p, K.VAULT)}")
        print("     下一步：让 LLM 按 schema 产出 judgements.json，再跑")
        print(f'     python tools/sci_protocol_gen.py --goal "{args.goal}" '
              f'--judges "<judgements.json>"')
        return 0

    if args.judges:
        with open(args.judges, "r", encoding="utf-8") as f:
            payload = json.load(f)
        judges = payload if isinstance(payload, list) else (payload.get("judgements") or [])
        merged, stats = merge_assessments([s["method"] for s in selected], judges)
        print(f"[ok] 判断层合并：{stats['judged']} 个方法，"
              f"quote 校验 {stats['checked']} 条，失败 {stats['failed']}")
        for mid in merged:
            print(f"     - {mid}")

    md = render_strategy(args.goal, selected, args.category)
    md += render_chain_section({s["method"]["method_id"] for s in selected})
    if args.json:
        print(json.dumps([{"method_id": s["method"]["method_id"], "match": s["match"],
                           "quoted": s["quoted"], "bad": s["bad"],
                           "rank_score": s["rank_score"]} for s in selected],
                         ensure_ascii=False, indent=2))
    if not args.no_write:
        p_md = write_text(os.path.join(d, "strategy.md"), md)
        p_js = os.path.join(d, "strategy.json")
        write_text(p_js, json.dumps({
            "goal": args.goal, "category": args.category,
            "generated_at": datetime.date.today().isoformat(),
            "candidates": [{"method_id": s["method"]["method_id"],
                            "name_zh": s["method"]["name_zh"],
                            "category": s["method"]["category"],
                            "matched": s["match"], "quoted": s["quoted"],
                            "bad": s["bad"], "rank_score": s["rank_score"]}
                           for s in selected]}, ensure_ascii=False, indent=2))
        print(f"[ok] 策略层：{len(selected)} 个候选（目标「{args.goal}」）")
        for s in selected:
            m = s["method"]
            print(f"     - [{m.get('category')}] {m.get('name_zh')} "
                  f"（match={s['match']} 引文={s['quoted']}）")
        print(f"     输出: {os.path.relpath(p_md, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
